{
  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PARTIAL",
      "evidence": "A **20% cap—AUD 4.8 million—is not necessarily unacceptable for ordinary business warranties in isolation**."
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "seek a lower de minimis, aggregation of related claims, and a lower or tipping basket"
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PUSHBACK",
      "evidence": "Seek a longer general warranty period; preserve longer, tailored periods for title, tax and identified risks."
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Seek a cap of at least the purchase price, no de minimis or basket, and a materially longer claim period"
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "Include express fraud carve-outs and preserve statutory rights to the extent they cannot lawfully be excluded."
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Require fair disclosure with sufficient detail to identify the nature and scope of the relevant matter."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Prefer no knowledge exclusion; if conceded, limit it to actual knowledge of named Buyer individuals."
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "Do not deem the condition satisfied merely because a document labelled “consent” is delivered."
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "Require binding release arrangements effective at Completion, with subsequent registrations handled under enforceable undertakings."
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "expressly allocate their economic cost to the Seller through payment arrangements or an appropriate price deduction/debt-like adjustment."
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "Retain a broader specific indemnity for losses from pre-Completion payment or title defects"
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "Seek a specific indemnity for the pre-Completion incident"
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PARTIAL",
      "evidence": "Genuine ordinary-course costs for future services may properly remain with the business; unusual, accelerated or unauthorised commitments may require consent"
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "Specific protections must expressly prevail over inconsistent general limitations."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "DD-012 is relevant evidence, not comprehensive verification. Reconcile the register with supporting corporate records"
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "Fix the claims architecture:** confine general limitations to their intended scope and preserve meaningful fundamental, tax and identified-risk protection."
    }
  ],
  "adopts_framing": false,
  "adopts_framing_evidence": "",
  "names_manipulation": false
}

